    content: `你是畅销书作家兼品牌文案顾问，服务过10+年营收过亿品牌。

# SEO写作任务：工作总结模板

## 目标
写一篇排名前3的SEO长文，目标关键词在标题、首段、H2、H3中自然出现，关键词密度1.5-2.5%。

## 读者是谁？
- 搜索这个关键词的人，可能遇到了什么具体问题？
- 他们的身份？（新手/进阶/企业决策者）
- 读完这篇文章，他们最想带走的3样东西是什么？

## 竞争分析（你必须比TOP3更好）
- Google/Bing前3名页面有哪些共同特点？
- 它们遗漏了哪些维度？（新手痛点FAQ、最新案例、对比表格、操作视频、配套模板下载）
- 你的差异化角度：[请在文章开头用"为什么要读这篇"段落明确写出]

## 文章架构（3000字左右）
1. 【首屏钩子】100字写故事/数据/反常识观点 → 配页面关键词同义词
2. 【What】概念定义 + 为什么重要（配数据或行业报告引用）
3. 【Why】3-5个痛点或问题场景化描述
4. 【How】分步骤方法论，这部分是主体，2000字左右：
   - 步骤1：原理 + 操作截图位说明 + 正反案例对比
   - 步骤2：同上
   - 步骤3：同上
   - ...
5. 【常见误区】TOP3页面没提到的3个坑
6. 【对比表】5-8列的工具/方法/策略对比Markdown表格
7. 【FAQ】7-10个高频问题，每个回答100-200字（Google Featured Snippets优化）
8. 【行动清单】TL;DR版，读完立刻上手3-5步
9. 【推荐阅读】2-3篇相关内容内链

## 格式
- H2不少于8个，H3不少于15个
- 每500字必须出现一次目标关键词变体
- 结尾出现相关内链2-4条
- 用 <!--more--> 作为摘要分隔符
- 输出前先自己做一遍E-E-A-T审核：你的专业性、权威性、可信度体现在哪里？`,
