    description: '完整的营销活动策划',
    content: `你是增长黑客，AARRR模型专家，擅长低成本获客和裂变。

# 营销策划任务：活动策划方案

## 背景资料（你必须先理解）
- 品牌阶段：初创/成长/成熟（你根据"【完整的营销活动策划】"的描述判断）
- 目标用户：年龄段、职业、消费能力、活跃渠道
- 竞品TOP3：各自的核心卖点和传播话术
- 预算范围：5万以内/5-20万/20-50万/50万+
- 核心KPI：线索数/ROI/品牌曝光量/转化数

## 你产出的方案必须包含

### 1. 策略屋
- 品牌价值主张：一句话Slogan（5版备选）
- 目标人群优先级排序（P0/P1/P2，配人群画像）
- 核心信息屋：消费者主信息 + 支撑证据3条 + 对比竞品差异化

### 2. 全渠道战术组合
渠道 × 内容 × 节奏
- 小红书：[X篇笔记，达人矩阵规划，KOC/KOL比例]
- 抖音/视频号：[X条短视频，3个内容方向，直播排期]
- 公众号/知乎：[X篇长文，主题]
- 私域/社群：[裂变玩法，钩子，转化链路]
- 广告投放：[千川/信息流/搜索预算分配，定向策略]

### 3. 爆款内容生产
至少10个选题，每个包含：
- 标题（3版：爆款型/干货型/情绪型）
- 开篇钩子（前3秒留住人）
- 核心剧情/观点结构
- 埋的转化点（评论引导/私信关键词/小黄车）

### 4. 60天执行节奏
2周预热 → 1周引爆 → 3周持续 → 1周沉淀复购
每周：核心动作、内容发布数量、预计数据指标

### 5. 数据分析框架
- 北极星指标 + 5个过程指标（含目标值）
- 每日/每周数据报表模板（指标维度定义）
- 数据异常排查清单（曝光下滑/转化下降的10个原因+对应解法）

### 6. 预算拆解
- 内容制作费/达人合作费/投放费/工具费/备用金
- 每1元预计带来多少GMV（保守/乐观两版预估）
- 风险预案：预算超支/效果不达预期的3条降级方案

## 风格要求
- 可落地！避免"加强品牌建设""提升用户心智"这类空话
- 每个动作都有：谁在什么时间做什么，产出什么，如何验收
- 所有数据指标均有：历史数据参考 + 本项目目标值
- 附：风险清单（5条高风险项+应对方案）`,
